+                ON CONFLICT (dataset_id, instrument_id, date) DO NOTHING
+                """,
+                datasetId,
+                instrumentId,
+                date,
+                adjustedClose,
+                adjustedClose,
+                adjustedClose,
+                adjustedClose,
+                adjustedClose,
+                suspended,
+                carriedForward);
+    }
